const size_t PAGE_ALIGN = 0x1000; // Linker page size (4KB)

// Segment sizes from input Object Files (O.O.)
size_t O1_text_size = 0x8A0;
size_t O2_text_size = 0x300;

// 1. Linker combines segments
size_t combined_size = O1_text_size + O2_text_size; // 0xBA0

// 2. Pad to meet alignment constraints (e.g., page boundary)
size_t aligned_size = (combined_size + PAGE_ALIGN - 1)
                    & ~(PAGE_ALIGN - 1);

// Result: 0x1000 (Next aligned multiple)
size_t padding_added = aligned_size - combined_size; // 0x460
